def getResult(v1, v2):
    pattern = r"^(\d+)(?:\.(\d+))(?:\.(\d+))?(?:\-(.+))?$"

    major1, minor1, patch1, mile1 = re.findall(pattern, v1)[0]
    major2, minor2, patch2, mile2 = re.findall(pattern, v2)[0]

    if major1 != major2:
        if int(major1) > int(major2):
            return v1
        else:
            return v2

    if int(minor1) != int(minor2):
